-- Added by hand (ADR-0014, #394): the default drafts reworded, in the organization's `Trato` as its
-- rules have it now, each matched by the text it had; a text an organization wrote stays.
-- `turno_cancelado` and `turno_a_reprogramar` become one event template, `turno_no_disponible`:
-- their queued messages and notifications move to it, and their versions go, Meta's included
-- (no organization was live); it takes a name with a random suffix when one of the
-- organization's own has its name in any case, as `nameInUse` compares names. The reminder that asks to confirm starts with its buttons.
UPDATE `template` SET `draft` = CASE (SELECT `form_of_address` FROM `communication_rules` WHERE `id` = 1) WHEN 'usted' THEN 'Hola {{paciente}}! Le escribimos de {{organizacion}} para avisarle que su turno con {{profesional}} del {{fecha}} a las {{hora}} quedó reservado. Escríbanos por cualquier duda. Saludos!' ELSE 'Hola {{paciente}}! Te escribimos de {{organizacion}} para avisarte que tu turno con {{profesional}} del {{fecha}} a las {{hora}} quedó reservado. Escribinos por cualquier duda. Saludos!' END WHERE `draft` IN ('Hola {{paciente}}, te escribimos de {{organizacion}}: tu turno con {{profesional}} quedó reservado para el {{fecha}} a las {{hora}} en {{sede}} ({{direccion}}). Si necesitás cambiarlo, respondé este mensaje.', 'Hola {{paciente}}, le escribimos de {{organizacion}}: su turno con {{profesional}} quedó reservado para el {{fecha}} a las {{hora}} en {{sede}} ({{direccion}}). Si necesita cambiarlo, responda este mensaje.');
--> statement-breakpoint
