INSERT INTO `template` (`id`, `name`, `timing`, `timing_hours`, `draft`, `buttons`, `created_at`, `updated_at`) VALUES ('turno_no_disponible', CASE WHEN EXISTS (SELECT 1 FROM `template` WHERE lower(`name`) = 'turno no disponible') THEN 'Turno no disponible (' || lower(hex(randomblob(3))) || ')' ELSE 'Turno no disponible' END, NULL, NULL, CASE (SELECT `form_of_address` FROM `communication_rules` WHERE `id` = 1) WHEN 'usted' THEN 'Hola {{paciente}}! Le escribimos de {{organizacion}} para avisarle que lamentablemente {{profesional}} no va a poder atender su turno del {{fecha}} a las {{hora}}. Por favor, escríbanos si quiere sacar un turno nuevo.' ELSE 'Hola {{paciente}}! Te escribimos de {{organizacion}} para avisarte que lamentablemente {{profesional}} no va a poder atenderte el {{fecha}} a las {{hora}}. Por favor, escribinos si querés sacar un turno nuevo.' END, 'none', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000);
